def migrar_fk_assinatura(apps, dic):
    print("\nAtualizando Assinatura \n")
    Vinculo = apps.get_model('comum.Vinculo')
    Pessoa = apps.get_model('rh.Pessoa')
    Assinatura = apps.get_model('documento_eletronico.Assinatura')
    start_time_partial = datetime.datetime.now()
    habilitar_desabilitar_indices(table_name='documento_eletronico_assinatura', operation='DISABLE')
    for pessoa in tqdm.tqdm(Pessoa.objects.filter(assinatura__isnull=False).distinct()):
        criar_pessoa_externa(apps, dic, pessoa)

    # Curiosidade: O filtro por pessoa_id e vinculo_id só funciona aqui dentro da migration e
    # usando a entidade Vinculo entregue via parâmetro apps deste método. De todas as outras
    # formas o Django diz que tais atributos não existem, mesmo se vocẽ importar a entidade
    # Vinculo usado o apps de um "from django.apps import apps".
    # De fato tais atributos não existem na entidade, somente na tabela, mas achei curisoso
    # conseguir fazer queryes usando atributos do banco de dados aqui dentro da migration.
    vinculos_to_subquery = Vinculo.objects.filter(pessoa_id=OuterRef('pessoa_id'))
    assinaturas_to_update_vinculo = Assinatura.objects.annotate(vinculo_id_to_update=Subquery(vinculos_to_subquery.values('id')[:1]))
    '''
    Exemplo de SQL gerado pela ORM com o "annotate" realizado acima:
        SELECT  "documento_eletronico_assinatura"."id",
                "documento_eletronico_assinatura"."...",
                "documento_eletronico_assinatura"."nome_papel",
                "documento_eletronico_assinatura"."data_assinatura",
                "documento_eletronico_assinatura"."hmac",
                "documento_eletronico_assinatura"."papel_id",
                "documento_eletronico_assinatura"."pessoa_id",
                "documento_eletronico_assinatura"."vinculo_id",
                (
                    SELECT U0."id"
                    FROM "comum_vinculo" U0
                    WHERE U0."pessoa_id" = "documento_eletronico_assinatura"."pessoa_id"
                    LIMIT 1
                ) AS "vinculo_id_to_update"
        FROM    "documento_eletronico_assinatura"
        ORDER   BY "documento_eletronico_assinatura"."data_assinatura" DESC
    '''
    # Atualizando todas as assinaturas de uma só vez (Total de Registros; 2.369.365 registros de assinaturas - Banco do Suap de 09/OUT/2022)
    # Com esse ajuste, o procedimento que levava horas (num pc sem ssd o processo evoluia 1% a cada 36min em média, com perspectiva de atingir 100%
    # após 66 horas), passou a levar cerca de 5 minutos após esse dois ajustes (desabilitar os índices e fazer tudo num UPDATE só).
    assinaturas_to_update_vinculo.update(vinculo_id=F('vinculo_id_to_update'), skip_history=True)
    habilitar_desabilitar_indices(table_name='documento_eletronico_assinatura', operation='ENABLE')
    print(f'Duration: {datetime.datetime.now() - start_time_partial}')


