def migrar_fk_pessoa_para_fk_vinculo(apps, schema_editor):
    start_time_all = datetime.datetime.now()

    Vinculo = apps.get_model('comum.Vinculo')
    #
    vinculos = Vinculo.objects.all()
    dic = {vinculo.pessoa_id: vinculo.pk for vinculo in vinculos}

    #
    migrar_fk_interessados_documento_texto(apps, dic)
    migrar_fk_interessados_documento_digitalizado(apps, dic)
    migrar_fk_dono_documento(apps, dic)
    migrar_fk_solicitacao_revisao(apps, dic)
    migrar_fk_solicitacao_assinatura(apps, dic)
    migrar_fk_solicitacao_compartilhamento_doc_digitalizado_pessoa(apps, dic)
    migrar_fk_compartilhamento_documento_pessoa(apps, dic)
    migrar_fk_compartilhamento_documento_digitalizado_pessoa(apps, dic)
    migrar_fk_compartilhamento_setor_pessoa(apps, dic)
    migrar_fk_assinatura(apps, dic)

    print(f'Total Duration: {datetime.datetime.now() - start_time_all}')


