def _instalacao_vazia(apps):
    """Homolog/fresh: sem documentos, dumps de sanity check são no-op."""
    try:
        return not apps.get_model('documento_eletronico', 'DocumentoTexto').objects.exists()
    except Exception:
        return True


def dump_documento_eletronico_pessoa_fisica(apps, schema_editor):
    if _instalacao_vazia(apps):
        print('Skip dump pessoa_fisica: instalação sem documentos')
        return
    call_command('dump_documento_pessoafisica', executar_command_via_migration=True, directory=WORK_DIR)


def dump_documento_eletronico_vinculo(apps, schema_editor):
    if _instalacao_vazia(apps):
        print('Skip dump vinculo: instalação sem documentos')
        return
    call_command('dump_documento_vinculo', executar_command_via_migration=True, directory=WORK_DIR)


def check_dumps(apps, schema_editor):
    if _instalacao_vazia(apps):
        print('Skip check_dumps: instalação sem documentos')
        return
    file1_data = pd.read_csv(f'{WORK_DIR}/documento_eletronico_pessoa_md5sum.csv')
    file2_data = pd.read_csv(f'{WORK_DIR}/documento_eletronico_vinculo_md5sum.csv')
    for row1, row2 in zip(file1_data, file2_data):
        if row1 != row2:
            print("Checkagem falhou..... Rollback........")
            raise Exception("Sanity checking failed...........")


